ALTER TABLE "script_generation" ADD CONSTRAINT "script_generation_cost_currency_check" CHECK ((("script_generation"."estimated_cost_micros" is null and "script_generation"."actual_cost_micros" is null and "script_generation"."currency" is null) or (("script_generation"."estimated_cost_micros" is not null or "script_generation"."actual_cost_micros" is not null) and "script_generation"."currency" ~ '^[A-Z]{3}$')));
